/* Moderator console (W6, W7, W11, W19, W20, I3, I5, C2) and admin (J1, W21, I1, I2, H5, F4, F5) */

const PRI = { high: ["High", "flame"], med: ["Medium", "equal"], low: ["Low", "chevron-down"] };
const KIND = { dispute: ["scale", "coral"], hold: ["hourglass", "violet"], appeal: ["rotate-ccw", "sky"] };
const HOLD = { high_value_low_confidence: "High value, weak evidence (rule R4)", manipulation_risk: "Unusual rating pattern · 2 signals (level 4)", engine_failure: "Assessment didn't finish" };

const consoleHead = (t, s, a = "") => `<header class="ph" style="padding-top:24px"><div class="between" style="align-items:flex-end;flex-wrap:wrap"><div><h1 style="font-size:clamp(1.5rem,2.6vw,2rem)">${t}</h1>${s ? `<p>${s}</p>` : ""}</div>${a ? `<div class="btns">${a}</div>` : ""}</div></header>`;
function caseList(sel, base) {
  return `<div class="list">${DB.cases.map(c => `<a class="case" href="#${base}/case/${c.id}" data-k="${c.kind}" ${c.id === sel ? 'aria-current="true"' : ""}>
    <div class="between"><span class="prio ${c.prio}">${icon(PRI[c.prio][1])}${PRI[c.prio][0]}</span><span class="xs faint">${c.age} ago</span></div>
    <div class="row mt-2" style="align-items:flex-start">${photo(I(c.item).photo, { w: 120, ratio: "1", alt: "" }).replace('class="ph-img ', 'style="width:44px;border-radius:10px" class="ph-img ')}<div class="grow"><b class="small" style="display:block;line-height:1.35">${c.title}</b><span class="xs muted">${c.sub}</span></div></div>
    <div class="row-wrap mt-2"><span class="badge ${KIND[c.kind][1]}">${icon(KIND[c.kind][0])}${c.kind}</span><span class="mono xs faint">${c.state}</span></div></a>`).join("")}</div>`;
}
function decision(opts, writes, possession) {
  return `<form class="card card-pad-lg" id="dec" style="border:1.5px solid var(--primary)" novalidate><h3>Your decision</h3>
    <div class="opts mt-4">${opts.map(([t, d, ic], i) => `<label class="opt"><input type="radio" name="d" ${i === 0 ? "checked" : ""}>${tone(ic, "neutral", 34)}<span><strong>${t}</strong><p>${d}</p></span><span class="tick">${icon("check")}</span></label>`).join("")}</div>
    ${possession ? `<div class="field mt-6"><div class="label">Where is the item now?</div><div class="opts cols-2">${[["user", "With the lender"], ["hand", "With the borrower"], ["package-x", "Lost or destroyed"], ["circle-help", "Unknown"]].map(([ic, t], i) => `<label class="opt" style="padding:11px"><input type="radio" name="p" ${i === 0 ? "checked" : ""}>${tone(ic, "neutral", 30)}<span><strong class="small">${t}</strong></span></label>`).join("")}</div><span class="help">Decides whether the dates are released. If the borrower still has it, the booking stays held.</span></div>` : ""}
    <div class="field"><label class="label" for="why">Reason <span class="req">· both parties see this</span></label><textarea class="textarea" id="why" placeholder="What evidence led to this decision?"></textarea><div class="between xs faint mt-1"><span>Required, at least 20 characters</span><span id="wc">0</span></div><div id="we"></div></div>
    <p class="xs faint mt-2">${icon("scroll-text", "i-sm")} Writes ${writes}</p>
    <div class="btns mt-4"><button class="btn btn-primary" type="submit">Record decision</button><button class="btn btn-outline" type="button" id="ai">${icon("message-square-text")}Ask for information</button></div></form>`;
}
function bindDecision(base) {
  const f = $("#dec"); if (!f) return; const w = $("#why");
  w.oninput = () => { $("#wc").textContent = w.value.trim().length; w.removeAttribute("aria-invalid"); $("#we").innerHTML = ""; };
  f.onsubmit = e => { e.preventDefault(); if (w.value.trim().length < 20) { w.setAttribute("aria-invalid", "true"); $("#we").innerHTML = `<p class="err">${icon("circle-alert")}Write the reason before recording the decision.</p>`; refreshIcons(); w.focus(); return; }
    dialog(`<h2>Record this decision?</h2><p class="muted mt-2">It's signed with your name and can't be edited. Either party can appeal to a second moderator, and a reversal keeps both decisions in the log.</p><div class="card card-2 mt-4 small"><b>${$("input[name=d]:checked").closest("label").querySelector("strong").textContent}</b>${$("input[name=p]:checked") ? " · " + $("input[name=p]:checked").closest("label").querySelector("strong").textContent : ""}<p class="mt-1">${esc(w.value)}</p></div><div class="btns mt-6"><button class="btn btn-primary" id="cm" type="button">Record decision</button><button class="btn btn-ghost" data-close type="button">Go back</button></div>`, "Confirm");
    $("#cm").onclick = () => { closeDialog(); $(".detail").innerHTML = `<div class="card card-pad-lg">${done("Decision recorded", "Both parties have been notified with your reason. The audit log has a signed entry.")}<div class="btns" style="justify-content:center"><a class="btn btn-primary" href="#${base}">Next case</a></div></div>`; refreshIcons(); }; };
  $("#ai").onclick = () => dialog(`<h2>Ask for information</h2><div class="field mt-6"><div class="label">Ask</div>${seg([["b", "Borrower"], ["l", "Lender"], ["both", "Both"]])}</div><div class="field"><label class="label" for="iq">Question</label><textarea class="textarea" id="iq" style="min-height:80px">Do you have photos from when you collected the chairs?</textarea></div><div class="field"><div class="label">Reply within</div>${seg([["24", "24 h"], ["48", "48 h"], ["72", "72 h"]], 1)}<span class="help">With no reply in time, the case is marked “no response” and you decide with what's there.</span></div><button class="btn btn-primary btn-block mt-6" data-close type="button" onclick="toast('Question sent · 48 h deadline')">Send question</button>`, "Ask");
}
const caseTop = (c, chip, note) => `<div class="card card-pad-lg"><div class="between" style="align-items:flex-start;flex-wrap:wrap"><div><div class="xs faint mono">${c.id} · ${I(c.item).title}</div><h2 class="mt-1" style="font-size:1.4rem">${c.title}</h2></div>${chip}</div><p class="small muted mt-3">${icon("timer", "i-sm")} ${note}</p></div>`;
function disputeD(c) {
  const it = I(c.item), od = c.trigger === "overdue";
  return `<div class="stack-lg">${caseTop(c, stateChip("dispute", "DISPUTED"), od ? "Opened by the scheduler 5 h ago after 2 reminders. Assigned to you." : "Opened 2 h ago by the lender. Assigned to you. With no moderator after 24 h, it goes to the platform admin.")}
    ${od ? `<div class="card"><h3>What happened</h3><ul class="events-tr mt-4">${[["1 Oct", "", "handover_confirmed · both parties"], ["12 Oct 20:00", "h", "Due date passed"], ["12 Oct 20:05", "f", "reminder_sent · run 7a1c"], ["13 Oct 08:00", "f", "reminder_sent · second"], ["14 Oct 20:00", "a", "dispute_opened · ACTIVE → DISPUTED"]].map(([t, k, x]) => `<li><span class="tm">${t}</span><span class="pp ${k}"></span><span class="mono xs">${x}</span></li>`).join("")}</ul><p class="xs faint mt-3">Each job ran once. A rerun wouldn't send duplicate notices.</p></div>
      <div class="card card-2 row" style="align-items:flex-start">${av("u0", "sm")}<div><b class="small">Borrower replied 1 h ago</b><p class="small muted">“Sorry, my son took them to his hostel. They'll be back Friday.”</p></div></div>`
    : `<div class="card"><h3>What each side says</h3><div class="claims mt-4"><div class="claim"><div class="who">${av("u4", "xs")}Hira · lender</div>“Two chairs came back with cracked legs. They were fine at handover.”</div><div class="claim"><div class="who">${av("u0", "xs")}Sana · borrower</div>“Two already had scratches when I collected. Nothing broke while we had them.”</div></div></div>
      <div class="card"><h3>Photos</h3><div class="cmp mt-4"><div><div class="lab">${icon("package-check")}Handover</div>${photo(it.photo, { w: 500, ratio: "1", alt: "Handover" })}</div><div><div class="lab">${icon("undo-2")}Return</div>${photo(it.photo, { w: 500, ratio: "1", alt: "Return", cls: "flag", inner: '<span class="pin" style="left:28%;top:56%">1</span><span class="pin" style="left:64%;top:62%">2</span>' })}</div></div>
        <div class="check-row mt-2"><div><b class="small">“All 20 chairs, legs firm”</b><div class="xs" style="color:var(--primary-ink)">Ticked by both at handover</div></div><span class="badge coral">${icon("x")}2 cracked at return</span></div><div class="check-row"><div><b class="small">Listing note</b><div class="xs faint">“2 have scratches”, written by the lender</div></div><span class="badge">Scratches ≠ cracks</span></div></div>
      <div class="card"><h3>Event trail</h3><ul class="events-tr mt-4">${[["1 Oct 17:02", "", "request_accepted · ASSESSED → ACCEPTED"], ["1 Oct 18:10", "", "handover_confirmed · 2 photos · Rs 3,000"], ["3 Oct 20:15", "", "return_initiated · on time"], ["15 Oct 18:27", "a", "dispute_opened · RETURN_INITIATED → DISPUTED"], ["16 Oct 10:42", "h", "info_requested · borrower · 48 h"]].map(([t, k, x]) => `<li><span class="tm">${t}</span><span class="pp ${k}"></span><span class="mono xs">${x}</span></li>`).join("")}</ul><p class="xs faint mt-3">From the append-only event store. You can read this loan's chat only because a dispute is open.</p></div>
      <div class="card"><h3>Evidence about both</h3><p class="small muted mt-1">This dispute isn't counted for either of them until you decide.</p><div class="grid-2 mt-4"><div class="card card-2"><div class="row small">${av("u4", "xs")}<b>Hira as a lender</b></div><p class="xs muted mt-2">9 completed · no earlier disputes</p>${miniRange([9, 1.8], "sufficient")}</div><div class="card card-2"><div class="row small">${av("u0", "xs")}<b>Sana as a borrower</b></div><p class="xs muted mt-2">7 completed · 7 on time</p>${miniRange([16, 2.2], "sufficient")}</div></div></div>`}
    ${decision(od ? [["Extend to Friday", "Record an approved extension. The dispute closes when the books are back.", "calendar-plus"], ["Resolve as a late return", "Record a late outcome. It counts as evidence.", "clock-alert"], ["Resolve as not returned", "Record non-return and a deposit deduction agreed in person.", "package-x"]]
      : [["In favour of the lender", "The damage happened during the loan. Record a deposit deduction agreed in person.", "user"], ["In favour of the borrower", "Not enough evidence the damage is new. Release the deposit record in full.", "hand"], ["Shared responsibility", "Record a partial deduction and explain why.", "scale"]], "<code class='mono'>dispute_resolved</code>: DISPUTED → COMPLETED. The outcome then counts as evidence for both.", true)}</div>`;
}
function appealD(c) {
  const it = I(c.item);
  return `<div class="stack-lg">${caseTop(c, stateChip("held", "APPEAL"), "Appealed 1 h ago by the borrower. You're the second moderator and weren't involved in the first decision.")}
    <div class="card"><h3>Original decision · D-011</h3><div class="row mt-3">${av("mod2", "sm")}<div><b class="small">Rabia S.</b><div class="xs faint">12 Oct, 4:10 pm · in favour of the lender</div></div></div><p class="mt-3">“The return photo shows a split leg that isn't in the handover photo. Rs 600 deduction recorded.”</p></div>
    <div class="card"><h3>The appeal</h3><p class="mt-3" style="font-size:16.5px">“The leg was already split at pickup. It's in my pickup photo, which wasn't attached to the case.”</p>
      <div class="cmp mt-4"><div><div class="lab">${icon("camera")}Borrower's pickup photo · 5:12 pm</div>${photo(it.photo, { w: 500, ratio: "1", alt: "", cls: "flag", inner: '<span class="pin" style="left:60%;top:58%">!</span>' })}</div><div><div class="lab">${icon("package-check")}Lender's handover photo</div>${photo(it.photo, { w: 500, ratio: "1", alt: "" })}</div></div><p class="small muted mt-3">The pickup photo is timestamped 4 minutes before the handover was confirmed.</p></div>
    <div class="card"><h3>If you reverse it</h3><div class="stack mt-4">${[["history", "sky", "Both decisions stay in the log", "Rabia's is marked reversed, never deleted"], ["flag", "saffron", "Affected evidence is flagged", "This outcome is recalculated for both people"], ["banknote", "green", "Deduction record reversed", "Rs 600 marked returned to the borrower"]].map(([ic, t, h, d]) => `<div class="row" style="align-items:flex-start">${tone(ic, t, 34)}<div><b class="small">${h}</b><p class="xs muted">${d}</p></div></div>`).join("")}</div></div>
    ${decision([["Uphold the decision", "The first decision stands and the appeal closes.", "check-check"], ["Reverse the decision", "Decide for the borrower. The original stays in the log, marked reversed.", "rotate-ccw"], ["Partly reverse", "Change the deduction and explain why.", "scale"]], "<code class='mono'>appeal_decided</code>, plus <code class='mono'>decision_reversed</code> with flagged evidence if reversed.")}</div>`;
}
function holdD(c) {
  const risk = c.trigger === "manipulation_risk", fail = c.trigger === "engine_failure", it = I(c.item);
  const ex = [["Locality unclear or conflicting", "→ LOCALITY_CHECKED, then assess", "Same, with safeguards", "→ DECLINED"], ["Manipulation risk · high value, weak evidence", "→ ASSESSED with your note", "→ ASSESSED with safeguards", "→ DECLINED"], ["Assessment didn't finish", "→ LOCALITY_CHECKED, re-run", "Not available", "→ DECLINED"]];
  const body = risk ? `<div class="card"><h3>Trust and unusual activity, side by side</h3><p class="small muted mt-1">Never averaged. A strong history doesn't cancel unusual activity, and the activity alone never restricts anyone.</p>
      <div class="grid-2 mt-4"><div class="card card-2">${stateChip("sufficient")}<p class="small mt-3">8 completed loans in 3 weeks, all rated 5 stars.</p></div><div class="card card-2"><div class="between"><b class="small">Unusual activity</b><span class="kpi" style="font-size:1.4rem">72<span class="xs faint">/100</span></span></div><div class="meter mt-4"><i style="left:72%"></i></div><div class="between xs faint mt-2"><span>0</span><span>60 · hold line</span><span>100</span></div></div></div>
      <h4 class="mt-6 small">Signals found</h4>${[["Reciprocal ratings within a group of 4 accounts", 72], ["Very similar review text across them", 64], ["Ratings arriving faster than usual", 30]].map(([l, v]) => `<div class="signal"><span class="small">${l}</span><span class="sb"><i class="${v < 50 ? "lo" : ""}" style="width:${v}%"></i></span><b class="small mono">0.${v}</b></div>`).join("")}
      <p class="xs faint mt-3">Two signals at 0.5 or above, so it's held (ADR-0007). These are patterns to check, not proof.</p></div>`
    : fail ? `<div class="card">${empty("server-crash", "neutral", "No assessment exists", "The engine timed out at 09:41 and the failure was logged. No default state was given. Re-run it, or restrict if something else is wrong.")}</div>`
    : evidence({ ...DB.requests.r1.a, title: "Not enough similar history", lede: "Faisal N. has 1 completed loan (a book). This is a projector worth over Rs 60,000, so the history is thin and not similar.", ab: [2, 1.4], safeguards: [["Raise the recorded deposit", "Suggest Rs 10,000"], ["Hand over at the park gate", "A public spot"]], tech: { ...DB.requests.r1.a.tech, "Policy rule": "R4 · high value + weak or dissimilar evidence" } }, { name: "Faisal", interactive: false });
  return `<div class="stack-lg">${caseTop(c, stateChip("held", "HELD_FOR_REVIEW"), `Hold reason <span class="mono">${c.trigger}</span> · ${HOLD[c.trigger]}. The lender hasn't seen this request yet.`)}${body}
    <div class="card"><h3>What each decision does</h3><p class="small muted mt-1">Exits from HELD_FOR_REVIEW (ADR-0003). Your row is highlighted.</p><div style="overflow-x:auto"><table class="xt mt-3"><thead><tr><th>Hold reason</th><th>Clear</th><th>With safeguards</th><th>Restrict</th></tr></thead><tbody>${ex.map((r, i) => `<tr class="${i === (fail ? 2 : 1) ? "cur" : ""}">${r.map(x => `<td>${x}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>
    ${decision(fail ? [["Re-run the assessment", "Back to LOCALITY_CHECKED, and the engine runs again.", "rotate-cw"], ["Restrict: decline", "Human decision only. The borrower is told and can appeal.", "ban"]] : [["Clear", "Send to the lender with your note.", "check"], ["Clear with safeguards", "Send to the lender with the safeguards you choose.", "shield-check"], ["Restrict: decline", "Human decision only. The borrower is told and can appeal.", "ban"]], "<code class='mono'>hold_cleared</code> or <code class='mono'>request_declined</code>, with your reason in the audit log.")}</div>`;
}
function queue(sel, base, admin) {
  const c = DB.cases.find(x => x.id === sel);
  const n = k => DB.cases.filter(x => x.kind === k).length;
  return { title: c ? "Case " + c.id : "Case queue", nav: "queue",
    html: `${consoleHead(admin ? "Escalations" : "Good morning, Imran", admin ? "Cases with no moderator after 24 h, or involving a moderator. All communities." : "6 cases need a decision. 2 are high priority.")}
      ${c ? "" : `<div class="grid-4" data-stagger><div class="card" style="background:var(--text);color:var(--bg);border:0"><div class="xs" style="opacity:.7">High priority</div><div class="kpi mt-2" data-count="2">0</div></div><div class="card"><div class="xs faint">Disputes</div><div class="kpi mt-2" data-count="${n("dispute")}">0</div></div><div class="card"><div class="xs faint">Holds</div><div class="kpi mt-2" data-count="${n("hold")}">0</div></div><div class="card"><div class="xs faint">Median time to decide</div><div class="kpi mt-2">3.1 h</div></div></div>`}
      <div class="split-v mt-6 ${c ? "sel" : ""}"><div class="qlist"><div class="chips mb-4" data-chips id="qf" style="margin-bottom:12px">${[["all", "All", DB.cases.length], ["dispute", "Disputes", n("dispute")], ["hold", "Holds", n("hold")], ["appeal", "Appeals", n("appeal")]].map(([k, l, x], i) => `<button class="chip" type="button" data-f="${k}" aria-pressed="${i === 0}">${l}<span class="n">${x}</span></button>`).join("")}</div>${caseList(sel, base)}<p class="xs faint mt-3">${icon("info", "i-sm")} Ordered by trigger type, then age. Trust estimates never order the queue.</p></div>
        <div class="detail">${c ? `<a class="back mob" href="#${base}">${icon("arrow-left")}All cases</a>` + (c.kind === "dispute" ? disputeD(c) : c.kind === "appeal" ? appealD(c) : holdD(c)) : `<div class="card">${empty("mouse-pointer-click", "neutral", "Pick a case", "Start with high priority. A dispute freezes a loan until you decide.")}</div>`}</div></div>`,
    after() { bindDecision(base); $("#qf").addEventListener("click", e => { const b = e.target.closest("[data-f]"); if (b) $$(".case").forEach(r => (r.hidden = !(b.dataset.f === "all" || r.dataset.k === b.dataset.f))); }); } };
}
route("/mod", () => queue(null, "/mod"));
route("/mod/case/:id", ({ id }) => queue(id, "/mod"));
route("/admin/cases", () => queue(null, "/admin/cases", true));
route("/admin/cases/case/:id", ({ id }) => queue(id, "/admin/cases", true));

/* ---------------- W11: join requests ---------------- */
const LOCR = { verified: ["green", "Inside the boundary", "map-pin-check"], inconclusive: ["saffron", "Not checked (skipped)", "map-pin"], conflicting: ["coral", "Outside the boundary", "map-pin-off"] };
function members(sel) {
  const m = DB.joinRequests.find(x => x.id === sel);
  const list = `<div class="list">${DB.joinRequests.map(r => `<a class="case" href="#/mod/members/${r.id}" ${r.id === sel ? 'aria-current="true"' : ""}><div class="row"><span class="avatar">${r.initials}</span><div class="grow"><b class="small">${r.name}</b><div class="xs muted">${r.detail}</div></div><span class="xs faint">${r.age}</span></div><div class="row-wrap mt-2"><span class="badge ${LOCR[r.result][0]}">${icon(LOCR[r.result][2])}${LOCR[r.result][1]}</span>${r.flags.map(f => `<span class="badge coral">${icon("flag")}${f}</span>`).join("")}</div></a>`).join("")}</div>`;
  let d;
  if (!m) d = `<div class="card">${empty("user-check", "neutral", "Pick a request", "Unclear and conflicting results always come to a person. Nobody is rejected automatically.")}</div>`;
  else if (m.taken) d = `<div class="stack-lg"><div class="card card-pad-lg row"><span class="avatar xl">${m.initials}</span><div><h2>${m.name}</h2><p class="small muted">${m.detail}</p></div></div><div class="card card-2 row" style="align-items:flex-start">${tone("users", "sky", 36)}<div><b>${m.taken} approved this 2 minutes ago</b><p class="small muted">Your decision wasn't applied twice. If you disagree, reverse it with a reason. Both decisions stay in the log.</p></div></div><div class="card">${timeline([{ s: "done", t: "Request sent", d: "14 Oct" }, { s: "done", t: `Approved by ${m.taken}`, d: "15 Oct, 9:03 pm · “Inside boundary, invitation valid”" }, { s: "todo", t: "Reversal, only if needed" }])}</div><div class="btns"><a class="btn btn-outline" href="#/mod/members">Back to the queue</a><button class="btn btn-ghost" type="button" onclick="toast('A reversal needs a written reason', {ic:'info'})">${icon("rotate-ccw")}Reverse with a reason</button></div></div>`;
  else d = `<div class="stack-lg"><div class="card card-pad-lg"><div class="row" style="gap:18px"><span class="avatar xl">${m.initials}</span><div><h2 style="font-size:1.4rem">${m.name}</h2><p class="small muted">Email verified · joined 3 days ago · household account</p></div></div></div>
    <div class="card"><h3>Locality evidence</h3><p class="small muted mt-1">Only the result is stored. No coordinates, no address.</p>
      <div class="list mt-4" style="border:0"><div class="li" style="padding:12px 0">${tone(LOCR[m.result][2], LOCR[m.result][0], 38)}<span class="grow"><span class="d">One-time location check</span><span class="t">${LOCR[m.result][1]}</span><span class="d">${m.result === "conflicting" ? "Coarse area: DHA Phase 5, about 9 km from the boundary" : m.result === "inconclusive" ? "The applicant chose not to share location" : "Inside Block C"}</span></span></div>
      <div class="li" style="padding:12px 0">${tone("ticket", "saffron", 38)}<span class="grow"><span class="d">Invitation</span><span class="t">Code from ${m.id === "M-87" ? "Usman T." : "Bilal R."}</span><span class="d">Inviter is verified with no open disputes</span></span></div></div>
      ${m.flags.length ? `<div class="card card-2 row mt-2" style="align-items:flex-start">${tone("flag", "coral", 34)}<div><b class="small">${m.flags[0]}</b><p class="xs muted">A device signal, not proof. It could be a shared family phone. Ask before deciding.</p></div></div>` : ""}</div>
    <form class="card card-pad-lg" id="md" style="border:1.5px solid var(--primary)"><h3>Decision</h3><div class="opts mt-4">${[["Approve", "They can lend and borrow in Block C.", "user-check"], ["Ask for more information", "e.g. a utility bill showing the lane, account number hidden.", "message-square-text"], ["Reject", "They're told why and can apply again with new evidence.", "user-x"]].map(([t, x, ic], i) => `<label class="opt"><input type="radio" name="m" ${i === (m.result === "verified" ? 0 : 1) ? "checked" : ""}>${tone(ic, "neutral", 34)}<span><strong>${t}</strong><p>${x}</p></span><span class="tick">${icon("check")}</span></label>`).join("")}</div>
      <div class="field"><label class="label" for="mw">Reason <span class="req">· the applicant sees this</span></label><textarea class="textarea" id="mw" style="min-height:80px"></textarea></div><button class="btn btn-primary mt-4" type="submit">Record decision</button></form></div>`;
  return { title: "Join requests", nav: "members", html: `${consoleHead("Join requests", "3 people want to join Block C. 1 location result is unclear and 1 conflicts.")}<div class="split-v ${m ? "sel" : ""}"><div class="qlist">${list}</div><div class="detail">${m ? `<a class="back mob" href="#/mod/members">${icon("arrow-left")}All requests</a>` : ""}${d}</div></div>`,
    after() { $("#md")?.addEventListener("submit", e => { e.preventDefault(); if (!$("#mw").value.trim()) { $("#mw").setAttribute("aria-invalid", "true"); $("#mw").focus(); return toast("Add a reason. The applicant sees it.", { ic: "info" }); } $(".detail").innerHTML = `<div class="card card-pad-lg">${done("Decision recorded", `${m.name.split(" ")[0]} has been told, with your reason.`)}<div class="btns" style="justify-content:center"><a class="btn btn-primary" href="#/mod/members">Next request</a></div></div>`; refreshIcons(); }); } };
}
route("/mod/members", () => members(null));
route("/mod/members/:id", ({ id }) => members(id));

/* ---------------- I3 + I5: reports and automatic flags (iteration 3) ---------------- */
route("/mod/reports", () => ({ title: "Reports", nav: "reports", html: `${consoleHead("Reports and flags", "From members and from automatic screening. Nothing is ever removed automatically.")}${previewBar("The report queue and automatic screening (I3, I5)")}
  <div class="list mt-6" data-stagger>${DB.reports.map(r => `<div class="li" style="align-items:flex-start;flex-wrap:wrap">${tone(r.by.includes("Automatic") ? "bot" : "flag", r.prio === "high" ? "coral" : r.prio === "med" ? "saffron" : "sky", 38)}<span class="grow" style="min-width:220px"><span class="row-wrap"><span class="prio ${r.prio}">${icon(PRI[r.prio][1])}${PRI[r.prio][0]}</span><span class="badge">${r.what}</span><span class="xs faint">${r.by}</span></span><span class="t mt-1">${r.t}</span><span class="d">${r.why}</span></span><span class="btns"><button class="btn btn-outline btn-sm" type="button" onclick="toast('Kept, with reason logged')">Keep</button><button class="btn btn-outline btn-sm" type="button" onclick="toast('Warning sent')">Warn</button><button class="btn btn-danger btn-sm" type="button" onclick="toast('Removed. The author can appeal.')">Remove</button><button class="btn btn-ghost btn-sm" type="button" onclick="toast('Escalated to admin')">Escalate</button></span></div>`).join("")}</div>
  <p class="xs faint mt-4">${icon("info", "i-sm")} Reports clustered on one person are flagged as possible reporting abuse. Mixed Urdu and English text always goes to a person.</p>` }));
route("/mod/events", () => ({ title: "Event approvals", nav: "events", html: `${consoleHead("Event approvals", "Block C asks moderators to approve new events.")}${previewBar("Event approval (C2)")}
  <div class="grid-3 mt-6" data-stagger>${DB.events.slice(2, 5).map(e => `<div class="card" style="padding:0;overflow:hidden">${photo(e.photo, { w: 600, ratio: "16/9", alt: "" })}<div style="padding:16px"><span class="badge sky">${e.type}</span><h3 class="mt-2">${e.t}</h3><p class="small muted">${e.dow} ${e.day} ${e.mon} · ${e.where}</p><div class="row small mt-3">${av(e.org, "xs")}${U(e.org).name} · hosted 3 events, 70% attendance</div><div class="btns mt-4"><button class="btn btn-primary btn-sm" type="button" onclick="toast('Published to Block C')">Approve</button><button class="btn btn-outline btn-sm" type="button" onclick="toast('Changes requested')">Request changes</button></div></div></div>`).join("")}</div>` }));

/* ---------------- I6 / W21: audit log ---------------- */
function audit(admin, tamper) {
  return { title: "Audit log", nav: "audit", html: `${consoleHead("Audit log", "Every decision and state change, append-only.", `<button class="btn btn-outline btn-sm" type="button">${icon("download")}Export</button>`)}
    ${tamper ? `<div class="card row" style="background:var(--coral-soft);border:0;align-items:flex-start">${tone("shield-alert", "coral", 38)}<div><b>Integrity check failed at entry #1,281</b><p class="small">Its contents no longer match its hash, so the chain after it can't be trusted. Nothing was changed automatically, and the platform admin has been alerted.</p></div></div>`
      : `<div class="card card-2 row">${tone("shield-check", "green", 38)}<div><b class="small">Integrity check passed</b><p class="xs muted">1,284 entries, hash chain unbroken · checked 2 min ago. Entries can be added, never edited or deleted.</p></div></div>`}
    ${admin ? `<div class="card card-2 row mt-4" style="align-items:flex-start">${tone("chart-no-axes-column", "saffron", 38)}<div><b class="small">Worth a second look</b><p class="xs muted">Imran Q. decided 9 of the last 10 Block C disputes for lenders. This may be fine. It's flagged for review, not as a finding.</p></div></div>` : ""}
    <div class="row-wrap mt-6"><div class="input-wrap" style="flex:1;min-width:240px">${icon("search")}<input class="input" placeholder="Case, transaction or person" aria-label="Search the log"></div><div class="chips" data-chips>${["All", "Decisions", "State changes", "Scheduler", "Log views"].map((t, i) => `<button class="chip" type="button" aria-pressed="${i === 0}">${t}</button>`).join("")}</div></div>
    <div class="table-w mt-4"><table class="table"><thead><tr><th>#</th><th>When</th><th>Who</th><th>Action</th><th>Target</th><th>State change</th><th>Reason</th><th>As</th><th>Hash</th></tr></thead><tbody>${DB.audit.map(([n, t, who, role, act, tg, p, nx, why, auth, h]) => `<tr class="${tamper && n === 1281 ? "bad" : ""}"><td class="mono xs">${n}</td><td class="mono xs" style="white-space:nowrap">${t}</td><td><b class="small">${who}</b><div class="xs faint">${role}</div></td><td><span class="mono xs">${act}</span></td><td class="small">${tg}</td><td class="xs" style="white-space:nowrap">${p ? `${p} → <b>${nx}</b>` : "—"}</td><td class="small">${why || '<span class="faint">—</span>'}</td><td class="mono xs">${auth}</td><td class="mono xs ${tamper && n === 1281 ? "" : "faint"}">${tamper && n === 1281 ? "mismatch" : h}</td></tr>`).join("")}</tbody></table></div>
    <p class="xs faint mt-3">${icon("eye", "i-sm")} Personal details are masked. Opening this log is recorded too (you, just now).${admin && !tamper ? ` <a class="link" href="#/admin/audit/tamper">Prototype: show a tamper warning</a>` : ""}</p>` };
}
route("/mod/audit", () => audit(false));
route("/admin/audit", () => audit(true));
route("/admin/audit/tamper", () => audit(true, true));

/* ---------------- J1: admin analytics ---------------- */
const chartLine = (pts, col = "var(--primary)") => { const W = 600, H = 160, mx = Math.max(...pts); const P = pts.map((v, i) => [i * W / (pts.length - 1), H - 10 - v / mx * (H - 30)]); const d = P.map((p, i) => (i ? "L" : "M") + p[0].toFixed(1) + " " + p[1].toFixed(1)).join("");
  return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto" role="img" aria-label="Completed loans per week, rising"><defs><linearGradient id="lg" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${col}" stop-opacity=".25"/><stop offset="1" stop-color="${col}" stop-opacity="0"/></linearGradient></defs>${[0, 1, 2, 3].map(i => `<line x1="0" x2="${W}" y1="${20 + i * 40}" y2="${20 + i * 40}" stroke="var(--border)"/>`).join("")}<path d="${d}L${W} ${H}L0 ${H}Z" fill="url(#lg)"/><path d="${d}" fill="none" stroke="${col}" stroke-width="2.5" stroke-dasharray="1400" stroke-dashoffset="1400" style="animation:draw 1.6s var(--ease) forwards"/>${P.map(([x, y]) => `<circle cx="${x}" cy="${y}" r="3.5" fill="var(--surface)" stroke="${col}" stroke-width="2"/>`).join("")}</svg>`; };
route("/admin", () => ({ title: "Analytics", nav: "dash", html: `${consoleHead("Platform analytics", "All 4 communities · last 30 days", `<div class="chips" data-chips>${["7 days", "30 days", "Term"].map((t, i) => `<button class="chip" type="button" aria-pressed="${i === 1}">${t}</button>`).join("")}</div>`)}
  <div class="grid-4" data-stagger>${[["users", "green", 645, "Active members", "+38 this month"], ["package-check", "sky", 312, "Loans completed", "+18% vs last month"], ["scale", "coral", 3, "Open disputes", "Oldest 2 days"], ["hourglass", "violet", 7, "Requests held", "Median review 3.1 h"]].map(([ic, t, v, l, s]) => `<div class="card spot">${tone(ic, t)}<div class="kpi mt-4" data-count="${v}">0</div><b class="small">${l}</b><p class="xs faint">${s}</p></div>`).join("")}</div>
  <div class="grid-2 mt-6"><div class="card"><div class="between"><h3>Completed loans per week</h3><span class="badge green">${icon("trending-up")}Rising</span></div><div class="mt-4">${chartLine([12, 18, 15, 24, 22, 31, 29, 38, 42, 47])}</div></div>
    <div class="card"><h3>Evidence states on new requests</h3><p class="xs faint mt-1">They describe evidence for a loan, not people.</p><div class="bars mt-4">${[["Enough evidence", 54, "var(--primary)"], ["Review recommended", 21, "var(--saffron)"], ["Not enough history yet", 19, "var(--sky)"], ["Open dispute", 2, "var(--coral)"], ["Held for a moderator", 4, "var(--violet)"]].map(([l, v, c], i) => `<div class="br"><span class="small">${l}</span><span class="bt"><i style="width:${v}%;background:${c};animation-delay:${i * 80}ms"></i></span><b class="small">${v}%</b></div>`).join("")}</div></div></div>
  <div class="grid-2 mt-6"><div class="card"><h3>Communities</h3><div class="list mt-4">${DB.communities.map((c, i) => `<div class="li">${photo(c.photo, { w: 140, alt: "" })}<span class="grow"><span class="t">${c.name}</span><span class="d">${i === 2 ? "Fewer than 20 loans: figures hidden for privacy" : `${c.members} members · ${[168, 96, 0, 48][i]} loans`}</span></span>${i === 2 ? `<span class="badge">${icon("eye-off")}Hidden</span>` : ""}</div>`).join("")}</div></div>
    <div class="card"><div class="between"><h3>Other modules</h3>${soon()}</div><div class="grid-2 mt-4">${[["Forum posts", "—"], ["Assistant questions", "—"], ["Event registrations", "—"], ["Unanswered questions", "—"]].map(([l, v]) => `<div class="card card-2"><div class="xs faint">${l}</div><div class="kpi faint" style="font-size:1.4rem">${v}</div></div>`).join("")}</div><p class="xs faint mt-3">Tracked from iteration 3, once these modules launch.</p></div></div>` }));

